"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useRef, useState } from "react";

import { PlusIcon } from "@/components/blocks/parts/icons";
import { NumberTicker } from "@/components/motion/number-ticker";
import { Button } from "@/components/ui/button";

import { BlockFrame } from "../parts/block-frame";
import { type ApiKey, INITIAL_KEYS, sampleSecret } from "./api-keys/data";
import { CreateKeyForm, type NewKeyRequest } from "./api-keys/create-key-form";
import { KeyRow } from "./api-keys/key-row";
import { NewSecret } from "./api-keys/new-secret";
import { KeyIcon } from "./icons";

const EASE = [0.22, 1, 0.36, 1] as const;

/**
 * API key management for a clinic group: the active keys with their scopes
 * and last use, a Create key button that unfolds into its form in place, and
 * a new key's secret shown once.
 */
export function ApiKeys({ className }: { className?: string }) {
  const [keys, setKeys] = useState<ApiKey[]>(INITIAL_KEYS);
  const [creating, setCreating] = useState(false);
  const [fresh, setFresh] = useState<{ name: string; secret: string } | null>(null);
  const [announcement, setAnnouncement] = useState("");
  const createRef = useRef<HTMLButtonElement>(null);
  const titleId = useId();
  const reduceMotion = useReducedMotion();
  const fold = { duration: reduceMotion ? 0 : 0.26, ease: EASE };

  const close = () => {
    setCreating(false);
    requestAnimationFrame(() => createRef.current?.focus());
  };

  const create = ({ name, environment, scopes }: NewKeyRequest) => {
    const secret = sampleSecret(environment);
    const key: ApiKey = {
      id: `k${Date.now()}`,
      name,
      environment,
      lastFour: secret.slice(-4),
      scopes,
      idleDays: null,
      created: "11 Nov 2026",
      createdBy: "You",
      calls: 0,
    };
    setKeys((current) => [key, ...current]);
    setCreating(false);
    setFresh({ name, secret });
    setAnnouncement(`${name} created.`);
  };

  const revoke = (id: string) => {
    const key = keys.find((item) => item.id === id);
    setKeys((current) => current.filter((item) => item.id !== id));
    setAnnouncement(key ? `${key.name} revoked.` : "");
    requestAnimationFrame(() => createRef.current?.focus());
  };

  return (
    <BlockFrame aria-labelledby={titleId} className={className}>
      <header className="flex flex-wrap items-start justify-between gap-x-6 gap-y-3 border-b border-border px-5 py-4">
        <div className="flex min-w-0 max-w-md flex-col gap-1">
          <h2 id={titleId} className="flex items-center gap-2 text-base font-semibold">
            <KeyIcon aria-hidden="true" className="size-4 text-chart-1" />
            API keys
          </h2>
          <p className="text-sm text-muted-foreground">
            Keys act as your clinic group. Keep them on your server, never in a browser or in source control.
          </p>
        </div>
        <div className="flex items-center gap-4">
          <p className="text-sm text-muted-foreground">
            <span className="font-medium text-foreground tabular-nums">
              <NumberTicker value={keys.length} />
            </span>{" "}
            active
          </p>
          <Button ref={createRef} onClick={() => setCreating(true)} aria-expanded={creating} disabled={creating}>
            <PlusIcon aria-hidden="true" className="size-4" />
            Create key
          </Button>
        </div>
      </header>

      <AnimatePresence initial={false}>
        {creating ? (
          <motion.div
            key="form"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0, transition: { duration: reduceMotion ? 0 : 0.16 } }}
            transition={fold}
            className="overflow-hidden border-b border-border"
          >
            <CreateKeyForm onCreate={create} onClose={close} />
          </motion.div>
        ) : null}
        {fresh ? (
          <motion.div
            key="secret"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0, transition: { duration: reduceMotion ? 0 : 0.16 } }}
            transition={fold}
            className="overflow-hidden border-b border-border"
          >
            <NewSecret
              name={fresh.name}
              secret={fresh.secret}
              onDone={() => {
                setFresh(null);
                requestAnimationFrame(() => createRef.current?.focus());
              }}
            />
          </motion.div>
        ) : null}
      </AnimatePresence>

      {keys.length === 0 ? (
        <p className="px-5 py-8 text-center text-sm text-muted-foreground">No keys yet. Create one to connect an app.</p>
      ) : (
        <ul aria-label="Active keys" className="flex flex-col py-2">
          <AnimatePresence initial={false}>
            {keys.map((key) => (
              <motion.li
                key={key.id}
                layout={!reduceMotion}
                initial={reduceMotion ? false : { opacity: 0, y: -12 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, transition: { duration: reduceMotion ? 0 : 0.15 } }}
                transition={fold}
              >
                <KeyRow apiKey={key} onRevoke={revoke} />
              </motion.li>
            ))}
          </AnimatePresence>
        </ul>
      )}
      <p role="status" className="sr-only">
        {announcement}
      </p>
    </BlockFrame>
  );
}

"use client";

import { createContext, type ReactNode, type SVGProps, useContext } from "react";

import { cn } from "@/lib/utils";

import { FALLBACK_GLYPHS } from "./glyphs";
import type { BlockIconGlyphs, BlockIconName } from "./icon-names";

export type { BlockIconGlyphs, BlockIconName } from "./icon-names";

const GlyphContext = createContext<BlockIconGlyphs>(FALLBACK_GLYPHS);

/**
 * Hands the blocks under it the icons of one open-source pack. With no
 * provider, a block draws the glyphs in `./glyphs`: none on this site, which
 * always supplies a pack, and one open-source pack in an installed copy.
 */
export function BlockIconProvider({ glyphs, children }: { glyphs: BlockIconGlyphs; children: ReactNode }) {
  return <GlyphContext.Provider value={glyphs}>{children}</GlyphContext.Provider>;
}

/**
 * Makes an icon drawn from the chosen pack. Every name in `BLOCK_ICON_NAMES` is available. `turn` rotates the pack's glyph when the
 * pack has only one direction of it, such as an up arrow.
 */
export function packIcon(name: BlockIconName, turn?: string) {
  return function BlockIcon({ className, ...props }: SVGProps<SVGSVGElement>) {
    const glyph = useContext(GlyphContext)[name];
    return glyph ? <svg {...glyph} {...props} className={cn(turn, className)} /> : null;
  };
}

/** An icon no pack supplies, drawn here as plain strokes in the current colour. */
export function ownIcon(paths: ReactNode) {
  return function BlockIcon(props: SVGProps<SVGSVGElement>) {
    return (
      <svg
        aria-hidden="true"
        focusable="false"
        width="16"
        height="16"
        viewBox="0 0 16 16"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="round"
        strokeLinejoin="round"
        {...props}
      >
        {paths}
      </svg>
    );
  };
}

/** A warning triangle, from the chosen icon pack. */
export const AlertTriangleIcon = packIcon("alert-triangle");
/** An arrow that points down, from the chosen icon pack. */
export const ArrowDownIcon = packIcon("arrow-up", "rotate-180");
/** An arrow that points left, from the chosen icon pack. */
export const ArrowLeftIcon = packIcon("arrow-up", "-rotate-90");
/** An arrow that points up, from the chosen icon pack. */
export const ArrowUpIcon = packIcon("arrow-up");
/** A bell, from the chosen icon pack. */
export const BellIcon = packIcon("bell");
/** A calendar, from the chosen icon pack. */
export const CalendarIcon = packIcon("calendar");
/** A check mark, from the chosen icon pack. */
export const CheckIcon = packIcon("check");
/** A chevron that points down, from the chosen icon pack. */
export const ChevronDownIcon = packIcon("chevron-down");
/** A chevron that points right, from the chosen icon pack. */
export const ChevronRightIcon = packIcon("chevron-right");
/** A check mark in a circle, from the chosen icon pack. */
export const CircleCheckIcon = packIcon("circle-check");
/** A cross in a circle, from the chosen icon pack. */
export const CircleXIcon = packIcon("circle-x");
/** A download arrow, from the chosen icon pack. */
export const DownloadIcon = packIcon("download");
/** A globe, from the chosen icon pack. */
export const GlobeIcon = packIcon("globe");
/** An expand mark, from the chosen icon pack. */
export const MaximizeIcon = packIcon("expand");
/** A speech bubble, from the chosen icon pack. */
export const MessageIcon = packIcon("message");
/** A play mark, from the chosen icon pack. */
export const PlayerPlayFilledIcon = packIcon("play");
/** A plus, from the chosen icon pack. */
export const PlusIcon = packIcon("plus");
/** A refresh mark, from the chosen icon pack. */
export const RefreshIcon = packIcon("refresh");
/** Sparkles, from the chosen icon pack. */
export const SparklesIcon = packIcon("sparkles");
/** Two people, from the chosen icon pack. */
export const UsersIcon = packIcon("users");
/** A close mark, from the chosen icon pack. */
export const XIcon = packIcon("x");

/** Two arrows that cross, for swapping two things. */
export const ArrowsShuffleIcon = ownIcon(
  <>
    <path d="M2 4.5h2.2c1.2 0 2.3.6 3 1.6l1.6 3.8c.7 1 1.8 1.6 3 1.6H14" />
    <path d="M2 11.5h2.2c1 0 1.9-.4 2.6-1.1M9.2 5.6c.7-.7 1.6-1.1 2.6-1.1H14" />
    <path d="M12 2.5l2 2-2 2M12 9.5l2 2-2 2" />
  </>,
);

/** Six dots, for a handle a person drags. */
export const GripVerticalIcon = ownIcon(
  <path d="M6 3.5h.01M10 3.5h.01M6 8h.01M10 8h.01M6 12.5h.01M10 12.5h.01" strokeWidth="2" />,
);

/** Two bars, for pause. */
export const PlayerPauseFilledIcon = ownIcon(<path d="M5.5 3.5v9M10.5 3.5v9" strokeWidth="2.5" />);

/** A bin, for remove. */
export const TrashIcon = ownIcon(
  <>
    <path d="M2.5 4.5h11M6 4.5V3a.5.5 0 0 1 .5-.5h3A.5.5 0 0 1 10 3v1.5" />
    <path d="M4 4.5l.6 8a1 1 0 0 0 1 .9h4.8a1 1 0 0 0 1-.9l.6-8M6.75 7v4M9.25 7v4" />
  </>,
);

import type { ComponentPropsWithoutRef } from "react";

import { cn } from "@/lib/utils";

/**
 * The surface every block sits on: one bordered card that names itself to
 * screen readers through `aria-label` or `aria-labelledby`.
 */
export function BlockFrame({ className, ...props }: ComponentPropsWithoutRef<"section">) {
  return (
    <section
      {...props}
      className={cn(
        "@container w-full overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-sm",
        className,
      )}
    />
  );
}

/** Which Fernhill environment a key works against. */
export type KeyEnvironment = "live" | "test";

/** One permission a key can hold. */
export interface KeyScope {
  id: string;
  label: string;
  /** What the scope lets the key do, read out in the create form. */
  hint: string;
}

/** One API key in the list. Only the last four characters of the secret are ever kept. */
export interface ApiKey {
  id: string;
  name: string;
  environment: KeyEnvironment;
  lastFour: string;
  scopes: string[];
  /** Days since the key last made a call, or null when it never has. */
  idleDays: number | null;
  created: string;
  createdBy: string;
  /** Calls in the last 7 days. */
  calls: number;
}

/** A key unused for this many days or more is flagged as one to revoke. */
export const STALE_AFTER_DAYS = 90;

/** Every scope a key can hold. */
export const SCOPES: KeyScope[] = [
  { id: "bookings:read", label: "bookings:read", hint: "See bookings and open slots" },
  { id: "bookings:write", label: "bookings:write", hint: "Create, move and cancel bookings" },
  { id: "patients:read", label: "patients:read", hint: "See patient names and contact details" },
  { id: "messages:send", label: "messages:send", hint: "Send reminders by text and email" },
  { id: "reports:read", label: "reports:read", hint: "Export visit and revenue reports" },
];

/** The keys the sample clinic group already has. */
export const INITIAL_KEYS: ApiKey[] = [
  {
    id: "k1",
    name: "Booking page widget",
    environment: "live",
    lastFour: "3f9a",
    scopes: ["bookings:read", "bookings:write"],
    idleDays: 0,
    created: "4 Aug 2026",
    createdBy: "Priya Natarajan",
    calls: 18_420,
  },
  {
    id: "k2",
    name: "Reminder sender",
    environment: "live",
    lastFour: "b21e",
    scopes: ["patients:read", "messages:send"],
    idleDays: 1,
    created: "12 May 2026",
    createdBy: "Tom Okafor",
    calls: 6_115,
  },
  {
    id: "k3",
    name: "Monthly report export",
    environment: "live",
    lastFour: "70cd",
    scopes: ["reports:read"],
    idleDays: 143,
    created: "2 Jan 2026",
    createdBy: "Ana Ruiz",
    calls: 0,
  },
  {
    id: "k4",
    name: "Staging checks",
    environment: "test",
    lastFour: "a71c",
    scopes: ["bookings:read", "bookings:write", "patients:read"],
    idleDays: 3,
    created: "20 Sep 2026",
    createdBy: "Priya Natarajan",
    calls: 942,
  },
];

const ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789";

/** Makes a sample secret. It always carries `demo`, so nobody mistakes it for a real key. */
export function sampleSecret(environment: KeyEnvironment): string {
  let tail = "";
  for (let index = 0; index < 20; index += 1) tail += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
  return `fh_${environment}_demo_${tail}`;
}

/** The masked form a key shows in the list. */
export const maskedKey = (key: Pick<ApiKey, "environment" | "lastFour">) => `fh_${key.environment}_••••${key.lastFour}`;

/** When a key last made a call, in words. */
export function lastUsedText(idleDays: number | null): string {
  if (idleDays === null) return "Never used";
  if (idleDays === 0) return "Used today";
  if (idleDays === 1) return "Used yesterday";
  return `Used ${idleDays} days ago`;
}

"use client";

import { type FormEvent, type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { SegmentedControl } from "@/components/motion/segmented-control";
import { Button } from "@/components/ui/button";
import { Checkbox } from "@/components/ui/checkbox";
import { Input } from "@/components/ui/input";

import { type KeyEnvironment, SCOPES } from "./data";

/** What a person filled in to make a key. */
export interface NewKeyRequest {
  name: string;
  environment: KeyEnvironment;
  scopes: string[];
}

/** Props for the form that makes a key. */
export interface CreateKeyFormProps {
  onCreate: (request: NewKeyRequest) => void;
  /** Closes the form. The parent returns focus to the button that opened it. */
  onClose: () => void;
}

const ENVIRONMENTS: { value: KeyEnvironment; label: string }[] = [
  { value: "test", label: "Test" },
  { value: "live", label: "Live" },
];

/**
 * The form a Create key button unfolds into: a name, an environment and the
 * scopes. Escape anywhere in it closes it.
 */
export function CreateKeyForm({ onCreate, onClose }: CreateKeyFormProps) {
  const [name, setName] = useState("");
  const [environment, setEnvironment] = useState<KeyEnvironment>("test");
  const [scopes, setScopes] = useState<string[]>(["bookings:read"]);
  const [tried, setTried] = useState(false);
  const nameRef = useRef<HTMLInputElement>(null);
  const nameId = useId();
  const errorId = useId();

  useEffect(() => nameRef.current?.focus(), []);

  const nameMissing = name.trim() === "";
  const scopesMissing = scopes.length === 0;
  const error = nameMissing ? "Give the key a name, such as the app that will use it." : scopesMissing ? "Pick at least one scope." : null;

  const submit = (event: FormEvent) => {
    event.preventDefault();
    setTried(true);
    if (error) {
      if (nameMissing) nameRef.current?.focus();
      return;
    }
    onCreate({ name: name.trim(), environment, scopes });
  };

  const onKeyDown = (event: KeyboardEvent) => {
    if (event.key !== "Escape") return;
    event.preventDefault();
    onClose();
  };

  return (
    <form onSubmit={submit} onKeyDown={onKeyDown} aria-label="New API key" className="flex flex-col gap-4 px-5 py-4" noValidate>
      <div className="grid gap-4 @lg:grid-cols-[1fr_auto]">
        <div className="flex flex-col gap-1.5">
          <label htmlFor={nameId} className="text-sm font-medium">
            Key name
          </label>
          <Input
            id={nameId}
            ref={nameRef}
            value={name}
            onChange={(event) => setName(event.target.value)}
            placeholder="Front desk tablet"
            aria-invalid={tried && nameMissing}
            aria-describedby={tried && error ? errorId : undefined}
            autoComplete="off"
          />
        </div>
        <div className="flex flex-col gap-1.5">
          <span className="text-sm font-medium">Environment</span>
          <SegmentedControl aria-label="Environment" options={ENVIRONMENTS} value={environment} onValueChange={setEnvironment} />
        </div>
      </div>
      <fieldset className="flex flex-col gap-2">
        <legend className="mb-2 text-sm font-medium">Scopes</legend>
        <div className="grid gap-2 @lg:grid-cols-2">
          {SCOPES.map((scope) => {
            const checked = scopes.includes(scope.id);
            return (
              <label key={scope.id} className="flex cursor-pointer items-start gap-2.5 rounded-lg py-1 text-sm">
                <Checkbox
                  className="mt-0.5"
                  checked={checked}
                  onCheckedChange={(value) =>
                    setScopes((current) => (value ? [...current, scope.id] : current.filter((id) => id !== scope.id)))
                  }
                />
                <span className="flex flex-col">
                  <span className="font-mono text-xs">{scope.label}</span>
                  <span className="text-xs text-muted-foreground">{scope.hint}</span>
                </span>
              </label>
            );
          })}
        </div>
      </fieldset>
      <div className="flex flex-wrap items-center justify-between gap-3">
        <p id={errorId} role="alert" className="text-sm text-marketing-orange-ink">
          {tried ? error : null}
        </p>
        <div className="flex gap-2">
          <Button type="button" variant="ghost" onClick={onClose}>
            Cancel
          </Button>
          <Button type="submit">Create key</Button>
        </div>
      </div>
    </form>
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { useId, useState } from "react";

import { AlertTriangleIcon, ChevronDownIcon } from "@/components/blocks/parts/icons";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { cn } from "@/lib/utils";

import { formatWhole } from "../../lib/format";
import { type ApiKey, STALE_AFTER_DAYS, lastUsedText, maskedKey } from "./data";

/** Props for one key in the list. */
export interface KeyRowProps {
  apiKey: ApiKey;
  onRevoke: (id: string) => void;
}

const EASE = [0.22, 1, 0.36, 1] as const;

/**
 * One API key: its name, environment, masked value, scopes and last use, with
 * an expander that holds who made it, its traffic and a two-step revoke.
 */
export function KeyRow({ apiKey, onRevoke }: KeyRowProps) {
  const [open, setOpen] = useState(false);
  const [confirming, setConfirming] = useState(false);
  const reduceMotion = useReducedMotion();
  const panelId = useId();
  const stale = apiKey.idleDays !== null && apiKey.idleDays >= STALE_AFTER_DAYS;

  return (
    <div className="group relative px-3 py-1">
      <span
        aria-hidden="true"
        className="pointer-events-none absolute inset-x-2 inset-y-0.5 rounded-xl bg-muted opacity-0 motion-safe:transition-opacity group-hover:opacity-60"
      />
      <div className="relative grid grid-cols-[1fr_auto] items-start gap-x-3 gap-y-2 px-2 py-2.5">
        <div className="flex min-w-0 flex-col gap-1.5">
          <div className="flex flex-wrap items-center gap-2">
            <h3 className="truncate text-sm font-medium">{apiKey.name}</h3>
            <Badge variant={apiKey.environment === "live" ? "default" : "secondary"}>
              {apiKey.environment === "live" ? "Live" : "Test"}
            </Badge>
            {stale ? (
              <Badge variant="secondary">
                <AlertTriangleIcon aria-hidden="true" />
                Unused for {apiKey.idleDays} days
              </Badge>
            ) : null}
          </div>
          <code className="truncate font-mono text-xs text-muted-foreground">{maskedKey(apiKey)}</code>
          <ul aria-label="Scopes" className="flex flex-wrap gap-1.5">
            {apiKey.scopes.map((scope) => (
              <li key={scope} className="rounded-md border border-border px-1.5 py-0.5 font-mono text-xs">
                {scope}
              </li>
            ))}
          </ul>
        </div>
        <div className="flex items-center gap-3">
          <p className="hidden text-right text-xs text-muted-foreground @md:block">
            <span className={cn("block", stale && "text-marketing-amber-ink")}>{lastUsedText(apiKey.idleDays)}</span>
            <span className="block">Created {apiKey.created}</span>
          </p>
          <Button
            variant="ghost"
            size="icon"
            aria-expanded={open}
            aria-controls={panelId}
            aria-label={`${open ? "Hide" : "Show"} details for ${apiKey.name}`}
            onClick={() => {
              setOpen(!open);
              setConfirming(false);
            }}
          >
            <ChevronDownIcon aria-hidden="true" className={cn("size-4 motion-safe:transition-transform", open && "rotate-180")} />
          </Button>
        </div>
      </div>
      <AnimatePresence initial={false}>
        {open ? (
          <motion.div
            id={panelId}
            key="panel"
            initial={{ height: 0, opacity: 0 }}
            animate={{ height: "auto", opacity: 1 }}
            exit={{ height: 0, opacity: 0, transition: { duration: reduceMotion ? 0 : 0.16 } }}
            transition={{ duration: reduceMotion ? 0 : 0.24, ease: EASE }}
            className="relative overflow-hidden"
          >
            <div className="flex flex-wrap items-end justify-between gap-3 px-2 pb-3">
              <dl className="grid grid-cols-2 gap-x-6 gap-y-1 text-xs @md:grid-cols-3">
                <div>
                  <dt className="text-muted-foreground">Created by</dt>
                  <dd>{apiKey.createdBy}</dd>
                </div>
                <div>
                  <dt className="text-muted-foreground">Calls, last 7 days</dt>
                  <dd className="tabular-nums">{formatWhole(apiKey.calls)}</dd>
                </div>
                <div className="@md:hidden">
                  <dt className="text-muted-foreground">Last use</dt>
                  <dd>{lastUsedText(apiKey.idleDays)}</dd>
                </div>
              </dl>
              {confirming ? (
                <div className="flex gap-2">
                  <Button variant="ghost" size="sm" onClick={() => setConfirming(false)}>
                    Keep key
                  </Button>
                  <Button variant="destructive" size="sm" onClick={() => onRevoke(apiKey.id)}>
                    Revoke now
                  </Button>
                </div>
              ) : (
                <Button variant="outline" size="sm" onClick={() => setConfirming(true)}>
                  Revoke
                </Button>
              )}
            </div>
          </motion.div>
        ) : null}
      </AnimatePresence>
    </div>
  );
}

const WHOLE = new Intl.NumberFormat("en-US", { maximumFractionDigits: 0 });
const ONE_PLACE = new Intl.NumberFormat("en-US", { minimumFractionDigits: 1, maximumFractionDigits: 1 });
const COMPACT = new Intl.NumberFormat("en-US", { notation: "compact", maximumFractionDigits: 1 });
const MONEY = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD", maximumFractionDigits: 0 });

/** A whole number with thousands separators. */
export const formatWhole = (value: number) => WHOLE.format(Math.round(value));

/** A number with one decimal place. */
export const formatOnePlace = (value: number) => ONE_PLACE.format(value);

/** A short number for an axis, such as 1.2K. */
export const formatCompact = (value: number) => COMPACT.format(value);

/** A dollar amount with no cents. */
export const formatMoney = (value: number) => MONEY.format(Math.round(value));

/** A percent with one decimal place and no sign. */
export const formatPercent = (value: number) => `${ONE_PLACE.format(Math.abs(value))}%`;

const DAY = new Intl.DateTimeFormat("en-US", { month: "short", day: "numeric", timeZone: "UTC" });
const WEEKDAY = new Intl.DateTimeFormat("en-US", { weekday: "long", timeZone: "UTC" });

/** The sample data ends on this day, so every block shows the same dates on every render. */
export const SAMPLE_END = Date.UTC(2026, 9, 31);

/** The date `daysBeforeEnd` days before the last sample day. */
export const sampleDate = (daysBeforeEnd: number) => new Date(SAMPLE_END - daysBeforeEnd * 86_400_000);

/** A short date, such as Oct 31. */
export const formatDay = (date: Date) => DAY.format(date);

/** A weekday name, such as Tuesday. */
export const formatWeekday = (date: Date) => WEEKDAY.format(date);

