  const headingRef = useRef<HTMLHeadingElement>(null);
  useEffect(() => headingRef.current?.focus(), []);

  return (
    <div className="relative flex flex-col gap-3 px-5 py-4">
      <span aria-hidden="true" className="pointer-events-none absolute inset-0 bg-marketing-green-surface opacity-60" />
      <h3 ref={headingRef} tabIndex={-1} className="relative flex items-center gap-2 rounded-sm text-sm font-semibold outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background">
